'use client';

import { useEffect, useRef, useState, type CSSProperties, type FormEvent, type ReactNode } from 'react';
import { Activity, ArrowDown, ArrowRight, ArrowUpRight, BookOpen, CalendarDays, Check, CheckCircle2, ChevronRight, Code2, Copy, Crown, Flame, Flag, Globe, LayoutDashboard, LockKeyhole, LogOut, Menu, MoreHorizontal, PenLine, Plus, RefreshCw, Search, Shield, ShieldCheck, Sparkles, Target, Trash2, Trophy, Users, X, Zap } from 'lucide-react';
import type { ApiResponse, AppState, CompetitionView, GoalTemplate, GoalView, Level, TaskChallenge, WeekDetail } from '../lib/types';

type Tab = 'overview' | 'goals' | 'competitions' | 'leaderboard' | 'history' | 'friends' | 'prime';
type Modal = { type: 'library' } | { type: 'add'; template: GoalTemplate } | { type: 'schedule'; goal: GoalView } | { type: 'task'; task: TaskChallenge } | { type: 'competition'; competition: CompetitionView } | { type: 'create' } | { type: 'join' } | null;
const NAV: { id: Tab; label: string; icon: typeof Target }[] = [
  { id: 'overview', label: 'Overview', icon: LayoutDashboard }, { id: 'goals', label: 'My goals', icon: Target },
  { id: 'competitions', label: 'Competitions', icon: Flag }, { id: 'leaderboard', label: 'Leaderboard', icon: Trophy }, { id: 'history', label: 'Your week', icon: CalendarDays }, { id: 'friends', label: 'Friends', icon: Users },
];
const LEVELS: Level[] = ['light', 'standard', 'stretch'];
const LEVEL_LABELS = { light: 'Light', standard: 'Standard', stretch: 'Stretch' };
const TIERS = ['Bronze', 'Silver', 'Gold', 'Platinum', 'Diamond'];
const SIGN_IN = '/login?return_to=%2F';
const SIGN_OUT = '/logout?return_to=%2F';

function initials(name: string) { return name.trim().split(/\s+/).slice(0, 2).map(x => x[0]).join('').toUpperCase() || 'K'; }
function dayLabel(date: string) { const d = new Date(/^\d{4}-\d{2}-\d{2}$/.test(date) ? `${date}T12:00:00` : date); return Number.isNaN(d.getTime()) ? date : d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }); }
function deadlineLabel(date: string) { const value = new Date(date); return Number.isNaN(value.getTime()) ? date : value.toLocaleString('en-US', { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short' }); }
function verificationLabel(v: string) { return v === 'quiz' ? 'Knowledge check' : v === 'writing' ? 'Written submission' : 'Self-reported'; }
function wordCount(text: string) { return text.trim().split(/\s+/).filter(Boolean).length; }
function Mark({ small = false }: { small?: boolean }) { return <span className={`brand-mark ${small ? 'small' : ''}`} aria-hidden="true"><span /><span /><span /></span>; }
function SkillIcon({ template, size = 22 }: { template?: Pick<GoalTemplate, 'category' | 'icon'>; size?: number }) { const key = `${template?.icon || ''} ${template?.category || ''}`.toLowerCase(); return key.includes('cod') || key.includes('program') || key.includes('tech') ? <Code2 size={size} /> : key.includes('writ') || key.includes('pen') ? <PenLine size={size} /> : key.includes('speak') || key.includes('comm') ? <Users size={size} /> : <BookOpen size={size} />; }
function Empty({ icon, title, children, action }: { icon: ReactNode; title: string; children: ReactNode; action?: ReactNode }) { return <div className="empty-state"><span className="empty-icon">{icon}</span><h3>{title}</h3><p>{children}</p>{action}</div>; }
function Spinner() { return <span className="spinner" aria-hidden="true" />; }
function RankBadge({ tier, large = false }: { tier: string; large?: boolean }) { return <span className={`rank-badge ${large ? 'large' : ''} rank-${tier.toLowerCase()}`}><Shield size={large ? 36 : 16} strokeWidth={1.7} /><span>{tier === 'Bronze' ? 'I' : tier === 'Silver' ? 'II' : tier === 'Gold' ? 'III' : tier === 'Platinum' ? 'IV' : 'V'}</span></span>; }

export default function KampitApp({ initialState }: { initialState?: AppState }) {
  const [state, setState] = useState<AppState | null>(initialState || null);
  const [loading, setLoading] = useState(!initialState);
  const [apiError, setApiError] = useState('');
  const [tab, setTab] = useState<Tab>('overview');
  const [modal, setModal] = useState<Modal>(null);
  const [busy, setBusy] = useState('');
  const [toast, setToast] = useState<{ text: string; error?: boolean } | null>(null);
  const [mobileNav, setMobileNav] = useState(false);
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('All');
  const [scope, setScope] = useState('');
  const [signIn, setSignIn] = useState(SIGN_IN);
  const [selectedLevel, setSelectedLevel] = useState<Level>('standard');
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [submission, setSubmission] = useState('');
  const [selfConfirmed, setSelfConfirmed] = useState(false);
  const [taskFeedback, setTaskFeedback] = useState('');
  const [formName, setFormName] = useState('');
  const [inviteCode, setInviteCode] = useState('');
  const [onboardingName, setOnboardingName] = useState('');
  const [interests, setInterests] = useState<string[]>([]);
  const [refreshing, setRefreshing] = useState(false);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);
  const [taskExpired, setTaskExpired] = useState(false);
  const [selectedWeek, setSelectedWeek] = useState('');
  const [weekDetail, setWeekDetail] = useState<WeekDetail | null>(null);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [historyError, setHistoryError] = useState('');
  const stateRef = useRef<AppState | null>(initialState || null);
  const scopeRef = useRef(scope); scopeRef.current = scope;
  const modalValueRef = useRef(modal); modalValueRef.current = modal;
  const revisionRef = useRef(0);
  const loadSequence = useRef(0);
  const historySequence = useRef(0);
  const mutatingRef = useRef(false);
  const refreshQueued = useRef(false);
  const loadAbort = useRef<AbortController | null>(null);
  const drafts = useRef(new Map<string, { date: string; text: string; answers: Record<string, number>; confirmed: boolean }>());
  const draftKey = (goalId: string) => `${stateRef.current?.viewer?.id || 'anonymous'}:${goalId}`;
  function commitState(next: AppState) {
    const opened = modalValueRef.current;
    if (opened?.type === 'task' && opened.task.taskDate && opened.task.taskDate !== next.today.date) setTaskExpired(true);
    if (stateRef.current?.viewer?.id !== next.viewer?.id) { setWeekDetail(null); setSelectedWeek(''); setModal(null); setTaskExpired(false); }
    stateRef.current = next; setState(next); setLastUpdated(new Date());
  }
  const inviteHandled = useRef(false);
  const modalRef = useRef<HTMLElement>(null);

  function notify(text: string, error = false) { setToast({ text, error }); }
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(null), 6000); return () => clearTimeout(t); }, [toast]);
  useEffect(() => {
    const current = new URL(window.location.href);
    const code = current.searchParams.get('join') || current.searchParams.get('invite');
    const returnTo = code ? `/?join=${encodeURIComponent(code.slice(0, 128))}` : '/';
    setSignIn(`/login?return_to=${encodeURIComponent(returnTo)}`);
    if (!initialState) void load();
  }, []); // Initial API state is authoritative.
  useEffect(() => {
    if (state?.viewer) { setOnboardingName(state.viewer.name); setInterests(state.viewer.interests || []); }
  }, [state?.viewer?.id]);
  useEffect(() => {
    if (!state?.viewer?.onboarded || inviteHandled.current) return;
    const url = new URL(window.location.href); const code = url.searchParams.get('join') || url.searchParams.get('invite');
    if (code) { inviteHandled.current = true; setInviteCode(code); setModal({ type: 'join' }); }
  }, [state?.viewer?.onboarded]);
  useEffect(() => {
    if (!modal && !(state?.viewer && !state.viewer.onboarded)) return;
    const old = document.body.style.overflow; document.body.style.overflow = 'hidden';
    const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const focusable = () => Array.from(modalRef.current?.querySelectorAll<HTMLElement>('button:not([disabled]):not([hidden]), a[href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])') || []).filter(element => element.offsetParent !== null);
    const frame = requestAnimationFrame(() => {
      const field = modalRef.current?.querySelector<HTMLElement>('input:not([disabled]), textarea:not([disabled]), select:not([disabled])');
      (field || focusable()[0] || modalRef.current)?.focus();
    });
    const keydown = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && state?.viewer?.onboarded) { event.preventDefault(); setModal(null); }
      if (event.key !== 'Tab') return;
      const nodes = focusable(); const first = nodes[0]; const last = nodes[nodes.length - 1];
      if (!first) { event.preventDefault(); modalRef.current?.focus(); return; }
      if (!modalRef.current?.contains(document.activeElement)) { event.preventDefault(); first.focus(); }
      else if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener('keydown', keydown);
    return () => { cancelAnimationFrame(frame); document.body.style.overflow = old; document.removeEventListener('keydown', keydown); if (previous?.isConnected) previous.focus(); };
  }, [modal?.type, state?.viewer?.onboarded]);

  useEffect(() => {
    const refreshVisible = () => { if (document.visibilityState === 'visible') void load(scopeRef.current, true); };
    window.addEventListener('focus', refreshVisible); window.addEventListener('online', refreshVisible);
    document.addEventListener('visibilitychange', refreshVisible);
    return () => { window.removeEventListener('focus', refreshVisible); window.removeEventListener('online', refreshVisible); document.removeEventListener('visibilitychange', refreshVisible); loadAbort.current?.abort(); };
  }, []);
  useEffect(() => {
    if (!state?.viewer) return;
    const boundaries = [state.today.nextResetAt, state.week.endsAt].map(x => new Date(x).getTime()).filter(Number.isFinite);
    if (!boundaries.length) return;
    const next = Math.min(...boundaries);
    const timer = setTimeout(() => {
      if (modalValueRef.current?.type === 'task') setTaskExpired(true);
      if (document.visibilityState === 'visible') void load(scopeRef.current, true);
    }, Math.max(500, Math.min(2_147_000_000, next - Date.now() + 750)));
    return () => clearTimeout(timer);
  }, [state?.today.nextResetAt, state?.week.endsAt, state?.viewer?.id]);
  useEffect(() => {
    if (tab !== 'leaderboard' || !state?.viewer) return;
    const timer = setInterval(() => { if (document.visibilityState === 'visible') void load(scopeRef.current, true); }, 30_000);
    return () => clearInterval(timer);
  }, [tab, state?.viewer?.id]);
  useEffect(() => {
    if (modal?.type !== 'task') return;
    drafts.current.set(draftKey(modal.task.goalId), { date: modal.task.taskDate, text: submission, answers, confirmed: selfConfirmed });
  }, [modal, submission, answers, selfConfirmed]);
  useEffect(() => {
    if (tab !== 'history' || !state?.viewer) return;
    const available = state.history || [];
    if (!available.length) { setSelectedWeek(''); setWeekDetail(null); return; }
    const id = available.some(week => week.id === selectedWeek) ? selectedWeek : available[0].id;
    if (id !== selectedWeek) { setSelectedWeek(id); return; }
    void loadHistory(id);
  }, [tab, selectedWeek, scope, state?.viewer?.id, state?.history?.map(week => week.id).join('|')]);

  async function load(selectedScope = scopeRef.current, quiet = false): Promise<AppState | null> {
    if (mutatingRef.current) { refreshQueued.current = true; return null; }
    const ticket = ++loadSequence.current; const revision = revisionRef.current;
    loadAbort.current?.abort(); const controller = new AbortController(); loadAbort.current = controller;
    if (!quiet) setRefreshing(true);
    try {
      const response = await fetch(`/api/kampit${selectedScope ? `?competitionId=${encodeURIComponent(selectedScope)}` : ''}`, { credentials: 'same-origin', cache: 'no-store', signal: controller.signal });
      const data = await response.json() as AppState & { error?: string };
      if (!response.ok) throw new Error(data.error || 'Could not load your workspace.');
      if (ticket !== loadSequence.current || revision !== revisionRef.current || mutatingRef.current) return null;
      commitState(data); setApiError(''); return data;
    } catch (error) {
      if (controller.signal.aborted || ticket !== loadSequence.current || revision !== revisionRef.current) return null;
      setApiError(error instanceof Error ? error.message : 'Could not connect to Kampit. Your current view is kept.'); return null;
    } finally { if (ticket === loadSequence.current) { setLoading(false); setRefreshing(false); } }
  }
  async function loadHistory(id: string) {
    const ticket = ++historySequence.current; const revision = revisionRef.current; const requestedScope = scopeRef.current; const viewer = stateRef.current?.viewer?.id;
    setHistoryLoading(true); setHistoryError(''); setWeekDetail(null);
    try {
      const params = new URLSearchParams({ historyWeek: id }); if (requestedScope) params.set('competitionId', requestedScope);
      const response = await fetch(`/api/kampit?${params}`, { credentials: 'same-origin', cache: 'no-store' });
      const data = await response.json() as WeekDetail & { error?: string };
      if (!response.ok) throw new Error(data.error || 'Could not open this week.');
      if (ticket !== historySequence.current || revision !== revisionRef.current || viewer !== stateRef.current?.viewer?.id || requestedScope !== scopeRef.current) return;
      setWeekDetail(data);
    } catch (error) { if (ticket === historySequence.current) setHistoryError(error instanceof Error ? error.message : 'Could not load this week.'); }
    finally { if (ticket === historySequence.current) setHistoryLoading(false); }
  }
  async function mutate(action: string, payload: Record<string, unknown> = {}): Promise<ApiResponse | null> {
    if (mutatingRef.current) return null;
    mutatingRef.current = true; revisionRef.current++; loadSequence.current++; loadAbort.current?.abort(); setRefreshing(false); setBusy(action);
    const requestedScope = scopeRef.current;
    try {
      const response = await fetch('/api/kampit', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action, payload: { ...payload, ...(requestedScope && !['demo', 'switch-demo', 'leave-demo'].includes(action) ? { viewCompetitionId: requestedScope } : {}) } }) });
      const data = await response.json() as ApiResponse & { error?: string; code?: string };
      if (!response.ok) {
        if (data.code === 'TASK_EXPIRED') { setTaskExpired(true); refreshQueued.current = true; }
        throw new Error(data.error || 'We could not save that. Please try again.');
      }
      commitState(data.state); setApiError('');
      if (data.message && action !== 'complete-goal') notify(data.message);
      if (['demo', 'switch-demo', 'leave-demo'].includes(action)) { scopeRef.current = ''; setScope(''); setSelectedWeek(''); setWeekDetail(null); }
      else if (scopeRef.current !== requestedScope) refreshQueued.current = true;
      if (['demo', 'leave-demo'].includes(action)) { setTab('overview'); setMobileNav(false); window.scrollTo({ top: 0, behavior: 'auto' }); }
      return data;
    } catch (error) { notify(error instanceof Error ? error.message : 'Something went wrong. Please try again.', true); return null; }
    finally {
      mutatingRef.current = false; setBusy('');
      if (refreshQueued.current) { refreshQueued.current = false; void load(scopeRef.current, true); }
    }
  }
  async function fetchTask(goalId: string, refreshExisting = false) {
    setBusy(`task-${goalId}`); setTaskFeedback('');
    try {
      const response = await fetch(`/api/kampit?goalId=${encodeURIComponent(goalId)}`, { credentials: 'same-origin', cache: 'no-store' });
      const data = await response.json() as TaskChallenge & { error?: string };
      if (!response.ok) throw new Error(data.error || 'Could not open today’s task.');
      const draft = drafts.current.get(draftKey(goalId));
      setSubmission(draft?.text || ''); setAnswers(draft?.date === data.taskDate ? draft.answers : {}); setSelfConfirmed(draft?.date === data.taskDate ? draft.confirmed : false);
      setTaskExpired(false); setModal({ type: 'task', task: data });
      if (refreshExisting && draft?.text) setTaskFeedback('Your writing draft was kept. Review today’s prompt before submitting it.');
      void load(scopeRef.current, true);
    } catch (error) { notify(error instanceof Error ? error.message : 'Could not open task.', true); } finally { setBusy(''); }
  }
  async function openTask(goal: GoalView) { await fetchTask(goal.id); }
  async function submitTask(event: FormEvent) {
    event.preventDefault(); if (modal?.type !== 'task') return;
    const resetAt = stateRef.current?.today.nextResetAt;
    if (taskExpired || (resetAt && Date.now() >= new Date(resetAt).getTime()) || modal.task.taskDate !== stateRef.current?.today.date) {
      setTaskExpired(true); void load(scopeRef.current, true); return;
    }
    const data = await mutate('complete-goal', { goalId: modal.task.goalId, taskDate: modal.task.taskDate, answers, text: submission });
    if (data?.result?.passed === false) { setTaskFeedback(data.result.feedback || data.message || 'Not quite yet. Review your answers and try again.'); return; }
    if (data) {
      drafts.current.delete(draftKey(modal.task.goalId)); setModal(null);
      const awarded = data.result?.awarded ?? 0;
      const explanation = [data.message, data.result?.feedback].filter(Boolean).join(' ');
      notify(`+${awarded} ranked points. ${explanation}`);
    }
  }
  async function copy(text: string) { try { await navigator.clipboard.writeText(text); notify('Copied to clipboard.'); } catch { notify(`Copy this: ${text}`); } }
  function go(next: Tab) { setTab(next); setMobileNav(false); setSearch(''); setCategory('All'); window.scrollTo({ top: 0, behavior: 'smooth' }); }
  function openSchedule(goal: GoalView) { setSelectedLevel(goal.nextLevel || goal.level); setModal({ type: 'schedule', goal }); }
  function openAdd(template: GoalTemplate) { setSelectedLevel('standard'); setModal({ type: 'add', template }); }

  const s = state;
  const firstName = s?.viewer?.name.split(' ')[0] || 'there';
  const categories = ['All', ...Array.from(new Set(s?.templates.map(t => t.category) || []))];
  const goalTemplate = (goal: GoalView) => s?.templates.find(t => t.id === goal.templateId);
  const weekTotal = s?.week.days.reduce((sum, day) => sum + day.score, 0) || 0;
  const incomplete = s?.goals.filter(g => !g.completedToday) || [];
  const friendGroups = s?.competitions.filter(c => c.kind === 'friends' && c.joined) || [];
  const recommended = s?.templates.filter(t => !s.goals.some(g => g.templateId === t.id)).sort((a, b) => Number(s.viewer?.interests.includes(b.category)) - Number(s.viewer?.interests.includes(a.category))).slice(0, 3) || [];
  const currentScope = s?.competitions.find(c => c.id === scope);
  const todayPercent = s?.today.plannedCount ? Math.min(100, Math.round(s.today.completedPlannedCount / s.today.plannedCount * 100)) : 0;
  const scheduleTemplate = modal?.type === 'schedule' ? s?.templates.find(template => template.id === modal.goal.templateId) : null;
  const currentTierIndex = TIERS.indexOf(s?.rank.tier || 'Bronze');

  function GoalCard({ goal }: { goal: GoalView }) {
    const template = goalTemplate(goal);
    return <article key={goal.id} className={`goal-card ${goal.completedToday ? 'completed' : ''}`}>
      <div className="goal-top"><span className="skill-icon" style={{ '--skill': template?.color || '#7465e8' } as CSSProperties}><SkillIcon template={template} /></span><div className="goal-kicker">{goal.category}<span>•</span>{LEVEL_LABELS[goal.level]}</div><button className="icon-button subtle" aria-label={`Archive ${goal.title}`} onClick={async () => { if (await mutate('archive-goal', { goalId: goal.id })) notify('Goal archived. Your earned points are kept.'); }} disabled={!!busy}><Trash2 size={15} /></button></div>
      <h3>{goal.title}</h3><p className="goal-description">{template?.levels[goal.level]?.description || template?.description}</p>
      <div className="goal-meta"><span><ShieldCheck size={13} />{verificationLabel(goal.verification)}</span><strong><Zap size={13} />{goal.points} pts</strong></div>
      <button className="schedule-action" onClick={() => openSchedule(goal)} disabled={!!busy}><CalendarDays size={14} /><span>{goal.nextLevel ? `Next week: ${LEVEL_LABELS[goal.nextLevel]}` : 'Plan next week’s level'}</span><ChevronRight size={13} /></button>
      {goal.nextLevel && <p className="pending-level">Starts {deadlineLabel(goal.nextLevelStartsAt || s!.week.endsAt)}</p>}
      <button className={`goal-action ${goal.completedToday ? 'done' : ''}`} disabled={!!busy || goal.completedToday} onClick={() => void openTask(goal)}>{busy === `task-${goal.id}` ? <Spinner /> : goal.completedToday ? <CheckCircle2 size={17} /> : <ArrowUpRight size={17} />}{goal.completedToday ? 'Done for today. Well played.' : 'Start today’s task'}</button>
    </article>;
  }
  function Leaderboard({ compact = false }: { compact?: boolean }) {
    const entries = compact ? s?.leaderboard.slice(0, 4) : s?.leaderboard;
    return entries?.length ? <div className={`leaderboard-table ${compact ? 'compact' : ''}`}>
      {!compact && <div className="leaderboard-row table-labels"><span>PLACE</span><span>COMPETITOR</span><span>RANK</span><span>STREAK</span><span>WEEKLY POINTS</span></div>}
      {entries.map((entry) => <div className={`leaderboard-row ${entry.isYou ? 'you' : ''}`} key={entry.userId}><span className={`place place-${entry.position}`}>{entry.position === 1 ? <Trophy size={compact ? 15 : 19} /> : String(entry.position).padStart(2, '0')}</span><span className="competitor"><span className={`avatar avatar-${entry.position % 4}`}>{initials(entry.name)}</span><span><strong>{entry.name}{entry.isYou && <small>You</small>}</strong>{compact && <em>{entry.tier}</em>}</span></span>{!compact && <span className="tier-inline"><RankBadge tier={entry.tier} />{entry.tier}</span>}{!compact && <span className="table-streak"><Flame size={15} />{entry.streak} days</span>}<strong className="table-score">{entry.score.toLocaleString()}<small> pts</small></strong></div>)}
    </div> : <Empty icon={<Trophy size={28} />} title="A fresh starting line" action={<button className="text-button" onClick={() => go('friends')}>Invite a friend <ArrowRight size={15} /></button>}>Complete a task or invite a friend to put your first points on the board.</Empty>;
  }
  function CompetitionCard({ competition }: { competition: CompetitionView }) {
    return <article key={competition.id} className={`competition-card ${competition.kind === 'global' ? 'global' : ''}`}>
      <div className="competition-visual"><span className="orbit one" /><span className="orbit two" /><span className="competition-symbol">{competition.kind === 'global' ? <Globe size={55} strokeWidth={1.2} /> : <Users size={55} strokeWidth={1.2} />}</span><span className={`tag ${competition.kind === 'global' ? 'prime-tag' : 'free-tag'}`}>{competition.kind === 'global' ? <><Crown size={12} /> PRIME</> : 'FRIENDS · FREE'}</span></div>
      <div className="competition-body"><div className="competition-type">{competition.kind === 'global' ? 'THE WORLD IS YOUR ARENA' : 'BETTER TOGETHER'}</div><h3>{competition.name}</h3><p>{competition.description}</p><div className="competition-data"><span><Users size={14} />{competition.members} {competition.members === 1 ? 'participant' : 'participants'}</span><span><CalendarDays size={14} />Ends {deadlineLabel(competition.endsAt)}</span></div><button className={competition.joined ? 'button secondary full' : 'button primary full'} onClick={() => setModal({ type: 'competition', competition })}>{competition.joined ? 'View competition' : competition.kind === 'global' && !s?.viewer?.primeDemo ? <><LockKeyhole size={15} />Explore with Prime</> : 'Explore competition'}<ArrowRight size={16} /></button></div>
    </article>;
  }

  const toastUI = toast && <div className={`toast ${toast.error ? 'error' : ''}`} role={toast.error ? 'alert' : 'status'}>{toast.error ? <Shield size={19} /> : <CheckCircle2 size={19} />}<span>{toast.text}</span><button className="icon-button" onClick={() => setToast(null)} aria-label="Dismiss notification"><X size={16} /></button></div>;

  if (loading) return <main className="loading-screen"><div className="brand"><Mark /><span>kampit<span className="brand-dot">.</span></span></div><Spinner /><p>Getting your next chapter ready…</p></main>;
  if (!s) return <main className="connection-screen"><div className="brand"><Mark /><span>kampit.</span></div><h1>Let’s reconnect.</h1><p>{apiError || 'Your workspace is taking a little longer to load.'}</p><button className="button primary" onClick={() => { setLoading(true); void load(); }}><RefreshCw size={17} />Try again</button>{toastUI}</main>;
  if (!s.viewer) return <div className="landing">
    <nav className="landing-nav"><div className="brand"><Mark /><span>kampit<span className="brand-dot">.</span></span></div><div className="landing-links"><a href="#how-it-works">How it works</a><a href="#the-league">The league</a></div><a href={signIn} target="_top" className="button secondary">Sign in <ArrowUpRight size={15} /></a></nav>
    <main className="landing-main"><section className="landing-hero"><div className="landing-copy"><div className="eyebrow"><span className="status-dot" />SMALL HABITS. REAL COMPETITION.</div><h1>Make showing up<br />your competitive<br /><span>edge.</span><svg viewBox="0 0 320 18" aria-hidden="true"><path d="M4 13 Q150 -6 315 11" /></svg></h1><p>You’ve got goals. Let’s make them stick. Build your skills, show up daily, and turn small wins into a bigger game — with friends or the world.</p><div className="hero-actions"><a className="button primary" href={signIn} target="_top">Find your momentum <ArrowRight size={17} /></a><button className="button text" disabled={!!busy} onClick={() => void mutate('demo')}>{busy === 'demo' ? <Spinner /> : <Sparkles size={17} />}Try the interactive demo</button></div><div className="hero-note"><ShieldCheck size={16} />Free with friends. Your effort sets the pace.</div></div><div className="landing-art"><div className="art-grid" /><div className="floating-tag"><Flame size={17} />Show up. Move up.</div><div className="preview-card"><div className="preview-top"><span>YOUR NEXT CHAPTER</span><span className="preview-dots"><i /><i /><i /></span></div><div className="preview-rank"><RankBadge tier="Bronze" large /><span>From first step<br /><strong>to personal best.</strong></span></div><div className="preview-task"><span className="skill-icon" style={{ '--skill': '#7365e9' } as CSSProperties}><Code2 /></span><div><strong>A little better, every day.</strong><small>Pick a skill. Choose your level.</small></div><span className="preview-check"><Check size={18} /></span></div><div className="preview-chart">{[30, 48, 42, 64, 58, 82, 100].map((height, i) => <span key={i} style={{ height: `${height}%` }}><i /></span>)}</div><div className="preview-chart-labels"><span>YOUR START</span><span>YOUR POTENTIAL <ArrowUpRight size={12} /></span></div></div><div className="floating-points"><Zap size={25} fill="currentColor" /><div><strong>One week.</strong><span>A fresh starting line.</span></div></div></div></section>
    <section id="how-it-works" className="how-section"><div className="section-heading"><div><span className="eyebrow">A BETTER WAY TO KEEP GOING</span><h2>Progress is a team sport.</h2></div><p>Different goals. One shared commitment<br />to showing up.</p></div><div className="how-grid">{[{ number: '01', icon: <Target />, title: 'Make it yours.', body: 'Choose a skill and a manageable daily challenge. Your level, your pace, your next step.' }, { number: '02', icon: <Zap />, title: 'Show up daily.', body: 'Complete a knowledge check or submit your work. Earn points and build your streak.' }, { number: '03', icon: <Trophy />, title: 'Rise together.', body: 'Compete with friends for free. Join the global weekly league with Prime.' }].map(item => <article key={item.number}><span className="how-number">{item.number}</span><span className="how-icon">{item.icon}</span><h3>{item.title}</h3><p>{item.body}</p></article>)}</div></section>
    <section id="the-league" className="league-landing"><div><span className="eyebrow">YOUR EFFORT HAS A PLACE HERE</span><h2>Different skills.<br />The same starting line.</h2><p>Weekly competitions, a shared daily points cap, and five ranks to grow through. Every week is another chance to put your commitment on the board.</p><button className="button lime" onClick={() => void mutate('demo')} disabled={!!busy}>Explore Kampit <ArrowUpRight size={17} /></button></div><div className="landing-ranks">{TIERS.map((tier, i) => <div key={tier} style={{ transform: `translateY(${Math.abs(2 - i) * 12}px)` }}><RankBadge tier={tier} large /><span>{tier}</span></div>)}</div></section></main><footer className="landing-footer"><div className="brand"><Mark small /><span>kampit.</span></div><span>A little progress. A lot of possibility.</span><small>Built for the web. Made for your next step.</small></footer>{toastUI}</div>;

  return <div className="app-shell">
    {mobileNav && <button className="nav-scrim" aria-label="Close navigation" onClick={() => setMobileNav(false)} />}
    <aside className={`sidebar ${mobileNav ? 'open' : ''}`}><button className="brand" onClick={() => go('overview')} aria-label="Kampit overview"><Mark /><span>kampit<span className="brand-dot">.</span></span></button><div className="sidebar-label">YOUR ARENA</div><nav aria-label="Main navigation">{NAV.map(item => <button className={tab === item.id ? 'active' : ''} onClick={() => go(item.id)} key={item.id}><item.icon size={19} /><span>{item.label}</span>{item.id === 'goals' && s.goals.length > 0 && <small>{s.goals.length}</small>}{tab === item.id && <span className="nav-active-dot" />}</button>)}</nav><div className="sidebar-bottom"><button className="sidebar-prime" onClick={() => go('prime')}><span className="prime-icon"><Crown size={18} /></span><strong>{s.viewer.primeDemo ? 'Prime demo is on' : 'Your next level awaits'}</strong><p>{s.viewer.primeDemo ? 'Explore the global experience.' : 'Meet your competition. Go global with Prime.'}</p><span>{s.viewer.primeDemo ? 'Manage demo access' : 'Explore Prime'}<ArrowUpRight size={15} /></span></button><div className="sidebar-profile"><span className="avatar profile-avatar">{initials(s.viewer.name)}</span><div><strong>{s.viewer.name}</strong><small>{s.mode === 'demo' ? 'Demo workspace' : s.viewer.primeDemo ? 'Prime demo access' : 'Free member'}</small></div>{s.mode === 'account' ? <a href={SIGN_OUT} target="_top" aria-label="Sign out"><LogOut size={16} /></a> : <button className="icon-button" onClick={() => void mutate('leave-demo')} aria-label="Leave demo"><LogOut size={16} /></button>}</div></div></aside>
    <div className="workspace"><header className="topbar"><div className="mobile-brand"><button className="icon-button" onClick={() => setMobileNav(true)} aria-label="Open navigation"><Menu size={22} /></button><Mark small /></div><div className="breadcrumb">Your arena <ChevronRight size={13} /><strong>{tab === 'prime' ? 'Kampit Prime' : NAV.find(x => x.id === tab)?.label}</strong></div><div className="topbar-right">{s.mode === 'account' && <button className="text-button" disabled={!!busy} onClick={() => void mutate('demo')}><Sparkles size={15} />Try demo</button>}<span className="week-chip"><CalendarDays size={14} />{s.week.label || 'This week'}</span><span className="topbar-divider" /><span className="mini-streak"><Flame size={17} />{s.today.streak}</span><span className="avatar mini-avatar">{initials(s.viewer.name)}</span></div></header>
      {s.mode === 'demo' && <div className="demo-banner"><span><Sparkles size={15} /><strong>Interactive demo</strong><span className="demo-detail">Fictional participants. Real tasks and saved progress.</span></span><div><button onClick={() => void mutate('switch-demo')} disabled={!!busy}><RefreshCw size={12} />Switch participant</button><button onClick={() => void mutate('leave-demo')} disabled={!!busy} aria-label="Leave interactive demo"><X size={16} /></button></div></div>}
      <main className="main-content">
        {apiError && <div className="inline-error" role="alert">{apiError}<button onClick={() => void load()}>Retry</button></div>}
        {tab === 'overview' && <>
          <section className="page-heading"><div><div className="eyebrow">LET’S MAKE TODAY COUNT</div><h1>You’re up, {firstName}<span className="wave">✳</span></h1><p>Your next small win is waiting. Take it one day at a time.</p></div><button className="button primary" onClick={() => setModal({ type: 'library' })}><Plus size={17} />Add a goal</button></section>
          <div className={`overview-hero ${s.today.planComplete ? 'plan-complete' : ''}`}><div className="momentum-card"><div className="momentum-copy"><span className="hero-pill"><span className="status-dot" />{s.today.planComplete ? 'TODAY’S PROMISES: KEPT' : 'THIS IS YOUR WEEK'}</span><h2>{s.today.planComplete ? <>You showed up.<br /><span>That’s a win.</span></> : <>Small steps.<br /><span>Serious momentum.</span></>}</h2><p>{s.today.planComplete ? 'Every goal on your daily plan is complete. Enjoy the progress you made.' : 'Keep your promises to yourself. Take the next manageable step.'}</p><button className="button dark" onClick={() => s.today.planComplete ? go('history') : incomplete[0] ? void openTask(incomplete[0]) : setModal({ type: 'library' })}>{s.today.planComplete ? 'See your week' : incomplete[0] ? 'Make your next move' : 'Find your first goal'}{s.today.planComplete ? <CheckCircle2 size={17} /> : <ArrowUpRight size={17} />}</button></div><div className="momentum-art" aria-hidden="true"><div className="art-ring ring-one" /><div className="art-ring ring-two" /><span className="art-star">✳</span><span className="step step-one" /><span className="step step-two" /><span className="step step-three" /><div className="art-runner">{s.today.planComplete ? <Check size={57} /> : <Zap size={57} fill="currentColor" />}</div><span className="art-label">{s.today.planComplete ? 'WELL PLAYED ✓' : 'KEEP GOING ↗'}</span></div></div><div className="daily-score-card"><div className="card-topline"><span>YOUR DAILY PLAN</span><Target size={16} /></div><div className="score-ring" style={{ '--progress': `${todayPercent * 3.6}deg` } as CSSProperties}><div><strong>{s.today.completedPlannedCount}/{s.today.plannedCount}</strong><span>goals complete</span></div></div><h3>{s.today.planComplete ? 'You’re done for today.' : s.today.plannedCount ? 'Your plan, one step at a time.' : 'Start with one small goal.'}</h3><p>{s.today.planComplete ? 'Your streak is safe. More goals are always optional.' : s.today.plannedCount ? `${s.today.plannedCount - s.today.completedPlannedCount} ${s.today.plannedCount - s.today.completedPlannedCount === 1 ? 'goal' : 'goals'} left in your plan.` : 'Choose a daily skill you’d like to grow.'}</p><div className="daily-points-separate"><span><Zap size={13} />{s.today.score}/{s.today.limit} ranked points</span><p>{s.today.score >= s.today.limit ? s.today.planComplete ? 'Daily ranking cap reached.' : 'Ranking cap reached. Your remaining goals still count toward your personal plan.' : 'This is a ranking limit, not a daily target.'}</p></div></div></div>
          <div className="quick-stats"><div><span className="stat-icon streak-icon"><Flame size={21} /></span><div><span>Current streak</span><strong>{s.today.streak}<small>{s.today.streak === 1 ? 'day' : 'days'}</small></strong></div><span className="stat-note">One task. Every day.</span></div><div><span className="stat-icon points-icon"><Zap size={21} /></span><div><span>This week</span><strong>{weekTotal}<small>pts</small></strong></div><span className="stat-note">New week. New chances.</span></div><div><span className="stat-icon rank-icon"><Shield size={21} /></span><div><span>Your rank</span><strong className="rank-stat">{s.rank.tier}</strong></div><button className="icon-button" aria-label="View rank details" onClick={() => go('leaderboard')}><ArrowUpRight size={19} /></button></div></div>
          <div className="dashboard-grid"><section className="today-section"><div className="section-heading"><div><h2>On your plate today <span className="count-badge">{s.goals.length}</span></h2><p>A little focus goes a long way.</p></div><button className="text-button" onClick={() => go('goals')}>All goals <ArrowRight size={15} /></button></div>{s.goals.length ? <div className="goal-grid">{s.goals.slice(0, 4).map(goal => GoalCard({ goal }))}</div> : <Empty icon={<Target size={30} />} title="Big things start small." action={<button className="button primary" onClick={() => setModal({ type: 'library' })}><Plus size={16} />Choose your first goal</button>}>Pick a skill you care about. We’ll help you turn it into something you can do today.</Empty>}
            {recommended.length > 0 && <div className="suggested-section"><div className="section-heading"><h2>A spark for your next step</h2><button className="text-button" onClick={() => setModal({ type: 'library' })}>Explore all <ArrowRight size={15} /></button></div><div className="suggested-grid">{recommended.map(template => <button className="suggested-card" key={template.id} onClick={() => openAdd(template)}><span className="skill-icon" style={{ '--skill': template.color } as CSSProperties}><SkillIcon template={template} size={20} /></span><span><small>{template.category}</small><strong>{template.title}</strong></span><Plus size={17} /></button>)}</div></div>}
          </section><aside className="dashboard-aside"><section className="panel activity-panel"><div className="section-heading"><h2>Your week in motion</h2><MoreHorizontal size={18} /></div><div className="activity-total"><strong>{weekTotal}</strong><span>points earned</span><span className="activity-up"><ArrowUpRight size={13} />This week</span></div><div className="activity-chart">{s.week.days.map(day => <div className={`chart-column ${day.date === s.today.date ? 'today' : ''}`} key={day.date}><span className="bar-value">{day.score || ''}</span><div className="bar-track"><div style={{ height: `${Math.max(4, Math.min(100, day.score))}%` }} title={`${day.label}: ${day.score} points`} /></div><span>{day.label.slice(0, 1)}</span></div>)}</div><div className="activity-footer"><span className="legend-dot" />Daily points<span>{s.rank.activeDays} active {s.rank.activeDays === 1 ? 'day' : 'days'}</span></div></section>
            <section className="panel mini-leaderboard"><div className="section-heading"><h2>Your competition</h2><button className="icon-button" onClick={() => go('leaderboard')} aria-label="Open leaderboard"><ArrowUpRight size={18} /></button></div><Leaderboard compact /><div className="panel-footer"><button className="text-button" onClick={() => go('leaderboard')}>See the full leaderboard <ArrowRight size={14} /></button></div></section>
            <div className="weekly-reminder"><CalendarDays size={20} /><div><strong>A fresh starting line, every week.</strong><p>This season ends {deadlineLabel(s.week.endsAt)}. Your rank and learning stay with you.</p></div></div></aside></div>
        </>}

        {tab === 'goals' && <><section className="page-heading"><div><div className="eyebrow">YOUR PROGRESS, YOUR PACE</div><h1>My goals<span className="heading-dot">.</span></h1><p>Keep the promises that move you forward.</p></div><button className="button primary" onClick={() => setModal({ type: 'library' })}><Plus size={17} />Add a goal</button></section><div className="goal-summary"><span><strong>{s.goals.length}</strong> active goals</span><span><strong>{s.today.completedPlannedCount}/{s.today.plannedCount}</strong> daily plan complete</span><span><Flame size={17} /><strong>{s.today.streak}</strong> day streak</span><span><Zap size={17} /><strong>{s.today.score}/{s.today.limit}</strong> daily points</span></div>{s.goals.length ? <div className="goal-grid full-goals">{s.goals.map(goal => GoalCard({ goal }))}</div> : <Empty icon={<Target size={32} />} title="Your next chapter starts here." action={<button className="button primary" onClick={() => setModal({ type: 'library' })}>Find a goal <ArrowRight size={16} /></button>}>Choose a template, pick your level, and take your first step.</Empty>}<div className="info-strip"><ShieldCheck size={18} /><p><strong>Same rules. Different goals.</strong> Levels and point values are set in advance. You can earn up to {s.today.limit} ranked points per day, across all your goals.</p></div></>}

        {tab === 'competitions' && <><section className="page-heading"><div><div className="eyebrow">FIND YOUR STARTING LINE</div><h1>Better with competition<span className="heading-dot">.</span></h1><p>Different skills. A shared reason to keep showing up.</p></div><button className="button secondary" onClick={() => { setFormName(''); setModal({ type: 'create' }); }}><Plus size={17} />Create with friends</button></section><div className="filter-row"><button className={category === 'All' ? 'filter-pill active' : 'filter-pill'} onClick={() => setCategory('All')}>All competitions</button><button className={category === 'friends' ? 'filter-pill active' : 'filter-pill'} onClick={() => setCategory('friends')}>With friends</button><button className={category === 'global' ? 'filter-pill active' : 'filter-pill'} onClick={() => setCategory('global')}><Globe size={14} />Global league</button></div><div className="competition-grid">{s.competitions.filter(c => category === 'All' || c.kind === category).map(competition => CompetitionCard({ competition }))}<button className="new-competition-card" onClick={() => { setFormName(''); setModal({ type: 'create' }); }}><span><Plus size={28} /></span><h3>Bring your people.</h3><p>A little friendly competition can go a long way.</p><strong>Create a free group <ArrowUpRight size={16} /></strong></button></div><div className="info-strip"><CalendarDays size={18} /><p><strong>One week. A clean slate.</strong> Weekly leaderboards reset together. Your ongoing streak and earned rank stay with you.</p></div></>}

        {tab === 'leaderboard' && <><section className="page-heading"><div><div className="eyebrow">EFFORT EARNS ITS PLACE</div><h1>The weekly leaderboard<span className="heading-dot">.</span></h1><p>Your skills may differ. Your commitment brings you together.</p></div><div className="leaderboard-tools"><button className="button secondary refresh-button" disabled={refreshing || !!busy} onClick={() => void load()}>{refreshing ? <Spinner /> : <RefreshCw size={15} />}Refresh</button><label className="scope-select"><span className="sr-only">Choose leaderboard</span><Flag size={15} /><select value={scope} disabled={!!busy} onChange={event => { scopeRef.current = event.target.value; setScope(event.target.value); void load(event.target.value); }}><option value="">Your current competition</option>{s.competitions.filter(c => c.kind === 'global' || c.joined).map(c => <option value={c.id} key={c.id}>{c.name}</option>)}</select></label></div></section><div className="live-board-note"><span className="status-dot" />Updates every 30 seconds while visible.{lastUpdated && <span>Last refreshed {lastUpdated.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })}</span>}</div><div className="leaderboard-layout"><div className="leaderboard-main"><div className="league-banner"><div><span className="eyebrow">{currentScope?.kind === 'friends' ? 'FRIENDS LEAGUE' : 'THIS WEEK’S ARENA'}</span><h2>{currentScope?.name || s.week.label}</h2><p>Season ends {deadlineLabel(s.week.endsAt)} · {s.today.limit} points daily cap</p></div><Trophy size={64} strokeWidth={1.15} /></div><section className="panel leaderboard-panel"><div className="section-heading"><h2>Commitment, on the board</h2>{s.mode === 'demo' && <span className="subtle-label">FICTIONAL DEMO PARTICIPANTS</span>}</div><Leaderboard /></section><div className="info-strip"><ShieldCheck size={18} /><p>Task checks follow each template’s rules. Knowledge checks are scored automatically; self-reported activities are labeled. Points reflect participation, not a certification of skill.</p></div></div><aside className="rank-panel panel"><span className="eyebrow">YOUR LONG GAME</span><RankBadge tier={s.rank.tier} large /><h2>{s.rank.tier}</h2><p>{s.rank.nextTier ? `Next stop: ${s.rank.nextTier}. Keep showing up to qualify for a rank move.` : 'You’re at the top tier. Keep setting the pace.'}</p><div className="rank-track">{TIERS.map((tier, i) => <div key={tier} className={i <= currentTierIndex ? 'reached' : ''}><span>{i < currentTierIndex ? <Check size={11} /> : ''}</span><small>{tier}</small></div>)}</div><div className="qualification"><span>Weekly qualification<strong>{s.rank.activeDays}/{s.rank.qualifyingDays} days</strong></span><div className="progress-track"><span style={{ width: `${Math.min(100, s.rank.activeDays / Math.max(1, s.rank.qualifyingDays) * 100)}%` }} /></div></div><div className="rank-rule"><ArrowUpRight size={17} /><p>Top 20% of eligible peers move up.</p></div><div className="rank-rule"><ArrowDown size={17} /><p>Bottom 20% may move down.</p></div><small className="rank-footnote">Rank changes need at least 10 eligible participants in your tier. Equal scores share a place. A tied group crossing either cutoff keeps its current tier. Everyone starts in Bronze.</small></aside></div></>}

        {tab === 'history' && <>
          <section className="page-heading"><div><div className="eyebrow">PROGRESS YOU CAN LOOK BACK ON</div><h1>Your week. Your proof<span className="heading-dot">.</span></h1><p>A record of the effort you actually put in — one completed week at a time.</p></div><div className="leaderboard-tools"><label className="scope-select"><span className="sr-only">Choose history competition</span><Flag size={15} /><select value={scope} disabled={!!busy} onChange={event => { scopeRef.current = event.target.value; setScope(event.target.value); setWeekDetail(null); void load(event.target.value); }}><option value="">Your current competition</option>{s.competitions.filter(competition => competition.kind === 'global' || competition.joined).map(competition => <option key={competition.id} value={competition.id}>{competition.name}</option>)}</select></label><button className="button secondary" disabled={refreshing || !!busy} onClick={() => void load()}>{refreshing ? <Spinner /> : <RefreshCw size={15} />}Refresh</button></div></section>
          <section className="current-week-card panel"><div><span className="eyebrow">IN PROGRESS · {s.week.label}</span><h2>You’re still writing this week’s story.</h2><p>Season ends {deadlineLabel(s.week.endsAt)}.</p></div><div className="current-week-numbers"><span><strong>{weekTotal}</strong>ranked points</span><span><strong>{s.rank.activeDays}</strong>active days</span><span><strong>{s.rank.tier}</strong>current rank</span></div></section>
          <div className="section-heading history-heading"><div><h2>Completed weeks</h2><p>{currentScope?.name || s.history?.[0]?.scopeName || 'Your current competition'} · Up to eight completed seasons</p></div></div>
          {!s.history?.length ? <Empty icon={<CalendarDays size={30} />} title="Your first chapter is still in progress." action={<button className="button primary" onClick={() => go('goals')}>Keep building your week <ArrowRight size={16} /></button>}>Your weekly summary will appear after your first completed season. Until then, your real progress is saved in the current week above.</Empty> : <div className="history-layout"><div className="history-weeks" role="group" aria-label="Completed seasons">{s.history.map(week => <button className={`history-week-card ${selectedWeek === week.id ? 'selected' : ''}`} onClick={() => setSelectedWeek(week.id)} key={week.id}><span>{week.label}<ChevronRight size={16} /></span><strong>{week.score}<small> pts</small></strong><p>{week.activeDays} active days · {week.completedCount} completions</p><small>{week.rankBefore && week.rankAfter ? week.rankBefore === week.rankAfter ? `Stayed ${week.rankAfter}` : `${week.rankBefore} → ${week.rankAfter}` : 'Rank snapshot unavailable'}</small></button>)}</div><section className="history-detail panel" aria-live="polite">{historyLoading ? <div className="history-loading"><Spinner /><p>Opening your week…</p></div> : historyError ? <Empty icon={<CalendarDays size={25} />} title="This week couldn’t be opened." action={<button className="button secondary" onClick={() => void loadHistory(selectedWeek)}>Try again</button>}>{historyError}</Empty> : weekDetail ? <><div className="history-detail-heading"><span className="eyebrow">{weekDetail.summary.scopeName}</span><h2>{weekDetail.summary.label}</h2><p>Ended {deadlineLabel(weekDetail.summary.endsAt)}</p></div><div className="history-summary-stats"><span><strong>{weekDetail.summary.score}</strong>ranked points</span><span><strong>{weekDetail.summary.activeDays}</strong>active days</span><span><strong>{weekDetail.summary.completedCount}</strong>completed tasks</span></div><div className="history-comparison"><Activity size={18} /><p>{weekDetail.summary.previousScore === null ? 'This is your first available completed week. There is no earlier score to compare yet.' : <><strong>{weekDetail.summary.score - weekDetail.summary.previousScore > 0 ? '+' : ''}{weekDetail.summary.score - weekDetail.summary.previousScore} points</strong> compared with the previous completed week ({weekDetail.summary.previousScore} points).</>}</p></div><div className="history-outcome"><div><Trophy size={20} /><span><strong>{weekDetail.summary.position === null ? 'Placement unavailable' : `Place ${weekDetail.summary.position}${weekDetail.summary.participants ? ` of ${weekDetail.summary.participants}` : ''}`}</strong><small>{weekDetail.summary.rankBefore && weekDetail.summary.rankAfter ? weekDetail.summary.rankBefore === weekDetail.summary.rankAfter ? `Rank held: ${weekDetail.summary.rankAfter}` : `${weekDetail.summary.rankBefore} → ${weekDetail.summary.rankAfter}` : 'Rank snapshot unavailable'}</small></span></div><p>{weekDetail.summary.rankReason}</p></div><div className="section-heading practice-heading"><h3>Your saved practice</h3><span>{weekDetail.activities.length} records</span></div>{weekDetail.activities.length ? <div className="practice-records">{weekDetail.activities.map(activity => <details key={activity.id} className="practice-record"><summary><span className="practice-record-icon">{activity.verification === 'writing' ? <PenLine size={17} /> : <CheckCircle2 size={17} />}</span><span><strong>{activity.title}</strong><small>{dayLabel(activity.date)} · {verificationLabel(activity.verification)}</small></span><span className="practice-points">{activity.points} pts<ChevronRight size={15} /></span></summary><div className="practice-record-body"><span className="field-label">Task prompt</span><p>{activity.prompt}</p>{activity.submission !== null && <><span className="field-label">Your saved submission</span><div className="saved-writing">{activity.submission}</div></>}{activity.submission === null && <p className="field-note">Completion recorded with the verification method shown above.</p>}</div></details>)}</div> : <p className="field-note">There are no saved practice records available for this completed season.</p>}</> : null}</section></div>}
        </>}

        {tab === 'friends' && <><section className="page-heading"><div><div className="eyebrow">A LITTLE FRIENDLY ACCOUNTABILITY</div><h1>Your people. Your pace<span className="heading-dot">.</span></h1><p>Turn “we should” into “we did.” Competing with friends is always free.</p></div><button className="button primary" onClick={() => { setFormName(''); setModal({ type: 'create' }); }}><Plus size={17} />Create a group</button></section><div className="friends-hero"><div className="friend-avatar-stack"><span>YOU</span><span><Users size={28} /></span><span>+1</span></div><div><h2>Build something together.</h2><p>Create a private competition, share the invite, and bring your own goals. You’ll have the same starting line every week.</p></div><button className="button dark" onClick={() => { setInviteCode(''); setModal({ type: 'join' }); }}>Join with a code <ArrowRight size={17} /></button></div><div className="section-heading"><h2>Your groups <span className="count-badge">{friendGroups.length}</span></h2><span className="subtle-label">PRIVATE · FREE</span></div>{friendGroups.length ? <div className="friend-groups">{friendGroups.map(group => <article className="panel friend-group" key={group.id}><div className="friend-group-top"><span className="skill-icon" style={{ '--skill': '#6b5ce7' } as CSSProperties}><Users size={24} /></span><span className="tag free-tag">FRIENDS</span></div><h3>{group.name}</h3><p>{group.members} {group.members === 1 ? 'participant' : 'participants'} · Ends {deadlineLabel(group.endsAt)}</p>{group.code && <div className="invite-box"><div><small>INVITE CODE</small><strong>{group.code}</strong></div><button className="icon-button" aria-label={`Copy invite code for ${group.name}`} onClick={() => void copy(group.code!)}><Copy size={17} /></button></div>}<div className="friend-group-actions"><button className="button secondary" onClick={() => { scopeRef.current = group.id; setScope(group.id); void load(group.id); go('leaderboard'); }}>View leaderboard <ArrowRight size={15} /></button>{group.code && <button className="icon-button" title="Copy invitation link" aria-label="Copy invitation link" onClick={() => void copy(`${window.location.origin}/?join=${encodeURIComponent(group.code!)}`)}><Copy size={17} /></button>}</div></article>)}</div> : <Empty icon={<Users size={32} />} title="Your starting line is open." action={<div className="empty-actions"><button className="button primary" onClick={() => { setFormName(''); setModal({ type: 'create' }); }}>Create a group <Plus size={16} /></button><button className="button secondary" onClick={() => setModal({ type: 'join' })}>I have a code</button></div>}>Invite one friend or your whole crew. Everyone can bring a different learning goal.</Empty>}{s.mode === 'demo' && <div className="info-strip"><Sparkles size={18} /><p>You’re exploring an isolated demo. Switch demo participants to try joining a group and watch the shared leaderboard update.</p></div>}</>}

        {tab === 'prime' && <><section className="page-heading"><div><div className="eyebrow">YOUR NEXT LEVEL</div><h1>Take your momentum global<span className="heading-dot">.</span></h1><p>Your friends are a great start. The world is waiting.</p></div></section><section className="prime-hero"><div className="prime-copy"><span className="prime-wordmark"><Crown size={19} />KAMPIT PRIME</span><h2>A bigger arena.<br /><span>The same you.</span></h2><p>Join the global weekly league, meet new competitors, and see where your consistency takes you.</p><div className="prime-features">{['Join open global competitions', 'Compete with your rank worldwide', 'Build momentum across different skills', 'A fresh weekly leaderboard'].map(feature => <span key={feature}><Check size={17} />{feature}</span>)}</div><div className="prime-action-box"><div><strong>Monthly membership</strong><small>Subscription checkout is not live yet.</small></div><button className="button lime" disabled={!!busy} onClick={() => void mutate('prime-demo', { enabled: !s.viewer?.primeDemo })}>{busy === 'prime-demo' ? <Spinner /> : <Crown size={17} />}{s.viewer.primeDemo ? 'Turn off demo access' : 'Try Prime demo access'}</button></div><div className="prime-disclosure"><ShieldCheck size={15} /><span>Demo access only. No payment details. No charge or subscription is created.</span></div></div><div className="prime-art" aria-hidden="true"><div className="prime-globe"><Globe size={180} strokeWidth={.8} /></div><div className="prime-orbit" /><span className="prime-spark one">✳</span><span className="prime-spark two">✦</span><span className="prime-art-tag"><Zap size={14} />SHOW UP. GO FURTHER.</span></div></section><div className="prime-comparison"><article className="panel"><span className="eyebrow">ALWAYS FREE</span><h3>Your goals. Your friends.</h3><p>Personal skill goals, daily streaks, private competitions, and friendly accountability.</p></article><article className="panel"><span className="eyebrow">WITH PRIME</span><h3>Your place in the world.</h3><p>Global weekly competitions and a worldwide rank alongside people working on their own next step.</p></article></div></>}
        <footer className="app-footer"><span>Small steps. Serious momentum.</span><span><Mark small />Kampit</span></footer>
      </main>
    </div>
    {toastUI}
    {(modal || !s.viewer.onboarded) && <div className="modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget && s.viewer?.onboarded) setModal(null); }}><section className={`modal ${modal?.type === 'library' ? 'wide' : ''}`} ref={modalRef} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby="modal-title"><button className="modal-close icon-button" aria-label="Close dialog" onClick={() => setModal(null)} hidden={!s.viewer.onboarded}><X size={20} /></button>
      {!s.viewer.onboarded ? <form onSubmit={async event => { event.preventDefault(); if (!onboardingName.trim() || !interests.length) return; await mutate('onboard', { name: onboardingName.trim(), interests, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'America/New_York' }); }}><span className="modal-emblem"><Mark /></span><span className="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h2 id="modal-title">Make it your arena.</h2><p className="modal-intro">A name, a few interests, and a little commitment. Let’s find your first step.</p><label className="field-label" htmlFor="display-name">What should we call you?</label><input id="display-name" name="displayName" className="input" autoFocus value={onboardingName} onChange={e => setOnboardingName(e.target.value)} maxLength={60} placeholder="Your name" required /><label className="field-label">What would you like to grow?</label><div className="interest-options">{categories.filter(c => c !== 'All').map(c => <button key={c} type="button" className={interests.includes(c) ? 'selected' : ''} onClick={() => setInterests(prev => prev.includes(c) ? prev.filter(x => x !== c) : [...prev, c])}>{interests.includes(c) && <Check size={14} />}{c}</button>)}</div><p className="field-note">You can explore any skill. This just helps you find a starting point.</p><button className="button primary full" disabled={!!busy || !onboardingName.trim() || !interests.length}>{busy === 'onboard' ? <Spinner /> : 'Let’s build some momentum'}<ArrowRight size={17} /></button><button type="button" className="button secondary full" style={{ marginTop: 12 }} disabled={!!busy} onClick={() => void mutate('demo')}><Sparkles size={17} />Explore the demo first</button></form> : modal?.type === 'library' ? <><span className="eyebrow">FIND YOUR NEXT STEP</span><h2 id="modal-title">What will you get better at?</h2><p className="modal-intro">Choose a skill. Pick your level. Build your own daily momentum.</p><div className="library-search"><Search size={18} /><input aria-label="Search goals" placeholder="Find your next skill…" value={search} onChange={e => setSearch(e.target.value)} autoFocus /></div><div className="filter-row modal-filters">{categories.map(c => <button key={c} className={category === c ? 'filter-pill active' : 'filter-pill'} onClick={() => setCategory(c)}>{c}</button>)}</div><div className="template-grid">{s.templates.filter(t => (category === 'All' || t.category === category) && `${t.title} ${t.category} ${t.description}`.toLowerCase().includes(search.toLowerCase())).map(template => <button className="template-card" onClick={() => openAdd(template)} key={template.id}><span className="skill-icon" style={{ '--skill': template.color } as CSSProperties}><SkillIcon template={template} /></span><small>{template.category}</small><h3>{template.title}</h3><p>{template.description}</p><span className="template-bottom"><span>{verificationLabel(template.verification)}</span><ArrowUpRight size={17} /></span></button>)}</div></> : modal?.type === 'add' ? <><span className="skill-icon large-icon" style={{ '--skill': modal.template.color } as CSSProperties}><SkillIcon template={modal.template} size={30} /></span><span className="eyebrow">{modal.template.category}</span><h2 id="modal-title">{modal.template.title}</h2><p className="modal-intro">{modal.template.description}</p><div className="field-label">Choose your daily commitment</div><div className="level-options">{LEVELS.map(level => <button key={level} className={selectedLevel === level ? 'selected' : ''} onClick={() => setSelectedLevel(level)}><div><span className="radio-dot">{selectedLevel === level && <span />}</span><strong>{LEVEL_LABELS[level]}</strong><span className="level-points"><Zap size={13} />{modal.template.levels[level].points} pts</span></div><p>{modal.template.levels[level].description}</p></button>)}</div><div className="task-rule"><ShieldCheck size={17} /><span>{verificationLabel(modal.template.verification)} · One credited completion per day. Your level stays fixed for the week.</span></div><button className="button primary full" disabled={!!busy} onClick={async () => { const data = await mutate('add-goal', { templateId: modal.template.id, level: selectedLevel }); if (data) { setModal(null); setTab('goals'); } }}>{busy === 'add-goal' ? <Spinner /> : <Plus size={17} />}Add this goal</button></>  : modal?.type === 'schedule' && scheduleTemplate ? <><span className="skill-icon large-icon" style={{ '--skill': scheduleTemplate.color } as CSSProperties}><SkillIcon template={scheduleTemplate} size={30} /></span><span className="eyebrow">PLAN YOUR NEXT CHAPTER</span><h2 id="modal-title">Next week’s commitment</h2><p className="modal-intro">Your current {LEVEL_LABELS[modal.goal.level]} level stays fixed for this week. Choose what fits your next week.</p><div className="schedule-current"><span>Current level<strong>{LEVEL_LABELS[modal.goal.level]}</strong></span><span>Change starts<strong>{deadlineLabel(s.week.endsAt)}</strong></span></div><div className="level-options">{LEVELS.map(level => <button key={level} className={selectedLevel === level ? 'selected' : ''} onClick={() => setSelectedLevel(level)}><div><span className="radio-dot">{selectedLevel === level && <span />}</span><strong>{LEVEL_LABELS[level]}</strong><span className="level-points"><Zap size={13} />{scheduleTemplate.levels[level].points} pts</span></div><p>{scheduleTemplate.levels[level].description}</p></button>)}</div><div className="task-rule"><CalendarDays size={17} /><span>This updates future tasks only. Earned points and this week’s task remain unchanged.</span></div><button className="button primary full" disabled={!!busy || (selectedLevel === modal.goal.level && !modal.goal.nextLevel)} onClick={async () => { const data = await mutate('schedule-level', { goalId: modal.goal.id, level: selectedLevel }); if (data) setModal(null); }}>{busy === 'schedule-level' ? <Spinner /> : <CalendarDays size={17} />}{selectedLevel === modal.goal.level ? modal.goal.nextLevel ? 'Cancel scheduled change' : 'Current level already selected' : `Schedule ${LEVEL_LABELS[selectedLevel]} for next week`}</button></>: modal?.type === 'task' ? <form onSubmit={submitTask}><span className="eyebrow">ONE STEP FORWARD</span><h2 id="modal-title">{modal.task.title}</h2><div className="task-modal-meta"><span><ShieldCheck size={14} />{verificationLabel(modal.task.verification)}</span><strong><Zap size={14} />Up to {modal.task.points} pts</strong></div><p className="task-prompt">{modal.task.prompt}</p>{taskExpired && <div className="task-expired" role="alert"><CalendarDays size={19} /><div><strong>A new day or season has started.</strong><p>Your draft is kept. Refresh the task and review today’s prompt before submitting.</p><button type="button" className="button secondary" disabled={!!busy} onClick={() => void fetchTask(modal.task.goalId, true)}>{busy ? <Spinner /> : <RefreshCw size={15} />}Refresh today’s task</button></div></div>}{modal.task.verification === 'quiz' && <div className="quiz-questions">{modal.task.questions?.map((q, i) => <fieldset key={q.id}><legend><span>{String(i + 1).padStart(2, '0')}</span>{q.question}</legend>{q.options.map((option, index) => <label className={answers[q.id] === index ? 'answer-option selected' : 'answer-option'} key={index}><input type="radio" name={q.id} value={index} checked={answers[q.id] === index} onChange={() => setAnswers(prev => ({ ...prev, [q.id]: index }))} required /><span>{String.fromCharCode(65 + index)}</span>{option}{answers[q.id] === index && <Check size={16} />}</label>)}</fieldset>)}</div>}{modal.task.verification === 'writing' && <div><label className="field-label" htmlFor="task-writing">Your submission</label><textarea id="task-writing" name="submission" className="input textarea" rows={8} value={submission} onChange={e => setSubmission(e.target.value)} placeholder="Make a little progress. Put it into words…" required /><div className="word-counter"><span>{wordCount(submission)} words</span><span>Minimum {modal.task.minWords || 20} words</span></div><p className="field-note">Kampit checks the submission length. This is a participation check, not an assessment of writing quality.</p></div>}{modal.task.verification === 'self' && <div className="self-report"><label><input type="checkbox" checked={selfConfirmed} onChange={e => setSelfConfirmed(e.target.checked)} required /><span>I completed this action today.</span></label><p>This activity is self-reported. Your competition will see the same verification label.</p></div>}{taskFeedback && <div className="task-feedback" role="alert">{taskFeedback}</div>}<button className="button primary full" disabled={!!busy || taskExpired || (modal.task.verification === 'writing' && wordCount(submission) < (modal.task.minWords || 20)) || (modal.task.verification === 'self' && !selfConfirmed)}>{busy === 'complete-goal' ? <Spinner /> : <CheckCircle2 size={17} />}{modal.task.verification === 'quiz' ? 'Check my answers' : 'Complete today’s task'}</button><p className="modal-fineprint">Your points are saved to the server. The daily limit applies across all goals.</p></form> : modal?.type === 'competition' ? <><span className="modal-emblem purple">{modal.competition.kind === 'global' ? <Globe size={30} /> : <Users size={30} />}</span><span className="eyebrow">{modal.competition.kind === 'global' ? 'GLOBAL LEAGUE · PRIME' : 'PRIVATE FRIENDS COMPETITION'}</span><h2 id="modal-title">{modal.competition.name}</h2><p className="modal-intro">{modal.competition.description}</p><div className="competition-detail-list"><span><Users size={17} />{modal.competition.members} participants</span><span><CalendarDays size={17} />Ends {deadlineLabel(modal.competition.endsAt)}</span><span><Zap size={17} />Up to {s.today.limit} ranked points per day</span><span><Target size={17} />Bring your own skill goals</span></div>{modal.competition.code && <div className="invite-box"><div><small>SHARE YOUR INVITE CODE</small><strong>{modal.competition.code}</strong></div><button className="icon-button" aria-label="Copy invite code" onClick={() => void copy(modal.competition.code!)}><Copy size={18} /></button></div>}{modal.competition.joined ? <button className="button primary full" onClick={() => { scopeRef.current = modal.competition.id; setScope(modal.competition.id); void load(modal.competition.id); setModal(null); go('leaderboard'); }}>Open the leaderboard <ArrowRight size={16} /></button> : modal.competition.kind === 'global' && !s.viewer.primeDemo ? <><div className="task-rule"><LockKeyhole size={17} /><span>You can explore this competition for free. Prime opens participation in the global league.</span></div><button className="button primary full" onClick={() => { setModal(null); go('prime'); }}><Crown size={17} />Explore Prime</button></> : <button className="button primary full" disabled={!!busy} onClick={async () => { const data = await mutate('join-competition', { competitionId: modal.competition.id }); if (data) setModal(null); }}>{busy === 'join-competition' ? <Spinner /> : <Flag size={17} />}Join this competition</button>}</> : modal?.type === 'create' ? <form onSubmit={async e => { e.preventDefault(); const data = await mutate('create-group', { name: formName.trim() }); if (data) { setModal(null); setTab('friends'); } }}><span className="modal-emblem purple"><Users size={28} /></span><span className="eyebrow">GOOD COMPANY. SHARED MOMENTUM.</span><h2 id="modal-title">Create your crew.</h2><p className="modal-intro">A private competition for your people. Different goals, one friendly leaderboard.</p><label className="field-label" htmlFor="group-name">Give your group a name</label><input className="input" id="group-name" name="groupName" autoFocus placeholder="The After-Work Achievers" value={formName} onChange={e => setFormName(e.target.value)} maxLength={60} required minLength={2} /><div className="task-rule"><ShieldCheck size={17} /><span>Free for everyone. Share the invite code with the people you want to join.</span></div><button className="button primary full" disabled={!!busy || formName.trim().length < 2}>{busy === 'create-group' ? <Spinner /> : <Plus size={17} />}Create free group</button></form> : modal?.type === 'join' ? <form onSubmit={async e => { e.preventDefault(); const data = await mutate('join-group', { code: inviteCode.trim() }); if (data) { setModal(null); setTab('friends'); window.history.replaceState({}, '', window.location.pathname); } }}><span className="modal-emblem purple"><Flag size={28} /></span><span className="eyebrow">YOUR PEOPLE ARE WAITING</span><h2 id="modal-title">Join the starting line.</h2><p className="modal-intro">Enter the invite code your friend shared. Your personal goals come with you.</p><label className="field-label" htmlFor="invite-code">Group invite code</label><input className="input code-input" id="invite-code" name="inviteCode" placeholder="Enter invite code" autoFocus value={inviteCode} onChange={e => setInviteCode(e.target.value)} required /><button className="button primary full" disabled={!!busy || !inviteCode.trim()}>{busy === 'join-group' ? <Spinner /> : <Users size={17} />}Join group</button></form> : null}
    </section></div>}
  </div>;
}
